  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills pipes with water up to the specified distance from the source using BFS.
   * Algorithm: If distance == 0, call fillBeginTile() to mark source as filled. Otherwise, for each coordinate in filledTiles from previous step, examine neighbors in the directions the pipe at that coordinate connects. If neighbor pipe exists and connects back (the outgoing direction of one pipe matches the opposite direction of the neighboring pipe) and is not already filled, mark it as filled and add to new filledTiles list. Update filledTiles with the new list. Update prevFilledDistance to current distance. Track number of newly filled tiles.
   * Related Features: filledTiles (List<Coordinate>), sourceCell (TerminationCell), prevFilledDistance (int), prevFilledTiles (int), cell (cellarray)
   * Related Classes: Coordinate, TerminationCell, Pipe, Direction, Pa19Helper
   * Input: distance: int - the current water flow distance (non-negative)
   * Output: void
   * Pre-condition: distance >= 0, sourceCell is defined and already marked as filled via fillBeginTile()
   * Post-condition: Water fills pipes reachable within the given distance from source according to pipe connectivity. The filledTiles list contains coordinates of all newly filled pipes at this distance.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance == 0) {
      fillBeginTile();
      getFilledTiles().clear();
      if (getSourceCell() != null && getSourceCell().getCoord() != null) {
        getFilledTiles().add(getSourceCell().getCoord());
      }
      prevFilledDistance = 0;
      prevFilledTiles = 1;
      return;
    }
    
    EList<Coordinate> newFilledTiles = new BasicEList<Coordinate>();
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    
    for (Coordinate coord : getFilledTiles()) {
      int r = coord.getRow();
      int c = coord.getCol();
      Cell cell = getCell()[r][c];
      EList<Direction> directions = new BasicEList<Direction>();
      
      if (cell instanceof FillableCell) {
        FillableCell fillableCell = (FillableCell) cell;
        Pipe pipe = fillableCell.getPipe();
        if (pipe != null && pipe.isFilled()) {
          directions.addAll(pipe.getConnections());
        }
      } else if (cell instanceof TerminationCell) {
        TerminationCell termCell = (TerminationCell) cell;
        if (termCell.isFilled()) {
          directions.add(termCell.getPointingTo());
        }
      }
      
      for (Direction dir : directions) {
        Direction opposite = helper.getOpposite(dir);
        Coordinate offset = helper.getOffset(dir);
        Coordinate neighborCoord = coord.add(offset);
        int nr = neighborCoord.getRow();
        int nc = neighborCoord.getCol();
        if (nr >= 0 && nr < getRows() && nc >= 0 && nc < getCols()) {
          Cell neighborCell = getCell()[nr][nc];
          if (neighborCell instanceof FillableCell) {
            FillableCell neighborFillable = (FillableCell) neighborCell;
            Pipe neighborPipe = neighborFillable.getPipe();
            if (neighborPipe != null && !neighborPipe.isFilled() && neighborPipe.getConnections().contains(opposite)) {
              neighborPipe.setFilled(true);
              newFilledTiles.add(neighborCoord);
            }
          } else if (neighborCell instanceof TerminationCell) {
            TerminationCell neighborTerm = (TerminationCell) neighborCell;
            if (!neighborTerm.isFilled() && neighborTerm.getPointingTo() == opposite) {
              neighborTerm.setFilled(true);
              newFilledTiles.add(neighborCoord);
            }
          }
        }
      }
    }
    
    prevFilledTiles = newFilledTiles.size();
    prevFilledDistance = distance;
    
    getFilledTiles().clear();
    getFilledTiles().addAll(newFilledTiles);
  }

